from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            True,
            1.0,
            False
        )
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute, Market.USA, True)
        self.option.SetFilter(self.OptionFilter)

        self.fast_period = 5
        self.slow_period = 20
        self.fast_values = []
        self.slow_values = []

        self.current_slice = None
        self.minute_bucket = None
        self.bucket_bars = {}
        self.previous_trading_date = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration_date = None
        self.expiration_processed_date = None

    def OptionFilter(self, universe):
        return universe.IncludeWeeklys().CallsOnly().Strikes(-100, 100).Expiration(0, 365)

    def OnData(self, slice):
        self.current_slice = slice

        current_date = self.Time.date()
        if self.previous_trading_date != current_date:
            if self.previous_trading_date is not None:
                self.previous_trading_date = self.previous_trading_date
            self.previous_trading_date = current_date

        self.HandleUnexpectedEquityPosition()
        self.ProcessExpiration()
        self.ProcessMinuteExit()

        bar = slice.Bars.get(self.spy_symbol)
        if bar is None:
            return

        local_time = bar.EndTime.astimezone(self.TimeZone).time()
        local_date = bar.EndTime.astimezone(self.TimeZone).date()

        if local_time < time(9, 30) or local_time > time(16, 0):
            return

        minute_index = local_time.hour * 60 + local_time.minute
        bucket_end_index = ((minute_index + 4) // 5) * 5
        bucket_end = time(bucket_end_index // 60, bucket_end_index % 60)

        if self.minute_bucket is None:
            self.minute_bucket = (local_date, bucket_end)

        if (local_date, bucket_end) != self.minute_bucket:
            self.FinalizeFiveMinuteBar(self.minute_bucket)
            self.minute_bucket = (local_date, bucket_end)
            self.bucket_bars = {}

        self.bucket_bars[bar.EndTime] = bar

        if len(self.bucket_bars) == 5:
            self.FinalizeFiveMinuteBar(self.minute_bucket)
            self.bucket_bars = {}
            self.minute_bucket = None

    def FinalizeFiveMinuteBar(self, bucket):
        if not self.bucket_bars:
            return

        bars = sorted(self.bucket_bars.values(), key=lambda x: x.EndTime)
        if len(bars) != 5:
            self.bucket_bars = {}
            return

        for i in range(1, len(bars)):
            if bars[i].EndTime - bars[i - 1].EndTime != timedelta(minutes=1):
                self.bucket_bars = {}
                return

        end_time = bars[-1].EndTime.astimezone(self.TimeZone)
        if end_time.time() < time(9, 35) or end_time.time() > time(16, 0):
            return

        close = bars[-1].Close
        self.fast_values.append(close)
        self.slow_values.append(close)

        if len(self.fast_values) > self.slow_period:
            self.fast_values.pop(0)
        if len(self.slow_values) > self.slow_period:
            self.slow_values.pop(0)

        if len(self.fast_values) < self.slow_period + 1:
            return

        previous_fast = sum(self.fast_values[-self.fast_period - 1:-1]) / self.fast_period
        previous_slow = sum(self.slow_values[-self.slow_period - 1:-1]) / self.slow_period
        current_fast = sum(self.fast_values[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.slow_values[-self.slow_period:]) / self.slow_period

        if not (time(9, 45) <= end_time.time() <= time(14, 30)):
            return

        bullish_cross = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if bullish_cross:
            self.TryEnterCall(close)

    def TryEnterCall(self, spy_price):
        if self.held_option is not None:
            return
        if self.entry_ticket is not None and self.entry_ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]:
            return
        if self.current_slice is None:
            return

        chains = list(self.current_slice.OptionChains)
        if not chains:
            self.Debug("Skipped call selection: no option chain.")
            return

        today = self.Time.date()
        eligible = []

        for chain in chains:
            for contract in chain:
                expiry = contract.Expiry.date()
                if contract.Right == OptionRight.Call and expiry >= today + timedelta(days=7):
                    eligible.append(contract)

        if not eligible:
            self.Debug("Skipped call selection: no eligible expiration.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in eligible)
        strike_floor = 1.01 * float(spy_price)

        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == nearest_expiry
            and float(contract.Strike) >= strike_floor
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying strike.")
            return

        selected = sorted(
            candidates,
            key=lambda c: (float(c.Strike), str(c.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.expiration_date = selected.Expiry.date()
        self.Debug(f"Call entry submitted: {selected.Symbol}")

    def ProcessMinuteExit(self):
        if self.held_option is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]:
            return

        security = self.Securities.get(self.held_option)
        if security is None:
            return

        bid = security.BidPrice
        ask = security.AskPrice
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self.exit_ticket = self.MarketOrder(
                self.held_option,
                -holding.Quantity
            )
            self.Debug(f"Profit target exit submitted: {self.held_option}")

    def ProcessExpiration(self):
        if self.held_option is None or self.expiration_date is None:
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested:
            return

        today = self.Time.date()
        previous_trading_day = self.PreviousTradingDay(self.expiration_date)

        if today == self.expiration_date:
            if self.expiration_processed_date != today:
                self.expiration_processed_date = today
                self.exit_ticket = self.MarketOrder(
                    self.held_option,
                    -holding.Quantity
                )
                self.Debug(f"Expiration liquidation submitted: {self.held_option}")
            return

        if today == previous_trading_day and self.Time.time() >= time(15, 45):
            if self.exit_ticket is None or self.exit_ticket.Status not in [
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            ]:
                self.exit_ticket = self.MarketOrder(
                    self.held_option,
                    -holding.Quantity
                )
                self.Debug(f"Time-stop exit submitted: {self.held_option}")

    def PreviousTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)
        while not self.Securities[self.spy_symbol].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)
        return candidate

    def HandleUnexpectedEquityPosition(self):
        holding = self.Portfolio[self.spy_symbol]
        if holding.Invested:
            self.MarketOrder(self.spy_symbol, -holding.Quantity)
            self.Debug("Unexpected SPY equity position liquidated.")

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    f"Call entry filled: {self.held_option}, "
                    f"price={self.entry_price}"
                )
            elif order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Call exit filled: {order_event.Symbol}")
                self.held_option = None
                self.entry_price = None
                self.expiration_date = None
                self.exit_ticket = None
                self.entry_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug("Unexpected option exercise or assignment received.")
        holding = self.Portfolio[self.spy_symbol]
        if holding.Invested:
            self.MarketOrder(self.spy_symbol, -holding.Quantity)
            self.Debug("SPY position from exercise or assignment liquidated.")

