        if self.held_symbol is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            return

        quote = slice.Bars.get(self.held_symbol)
        if quote is None:
            return

        bid = quote.Bid
        ask = quote.Ask

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self.CancelOpenExitOrders()
            self.exit_ticket = self.Liquidate(self.held_symbol)
            self.Debug("Profit target exit submitted: {}".format(self.held_symbol))

    def ProcessTimeStop(self, slice):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        previous_day = expiry - timedelta(days=1)

        while previous_day.weekday() >= 5:
            previous_day -= timedelta(days=1)

        if (
            self.Time.date() == previous_day
            and self.Time.time() >= time(15, 45)
        ):
            if self.exit_ticket is None or self.exit_ticket.Status.IsClosed():
                self.CancelOpenExitOrders()
                self.exit_ticket = self.Liquidate(self.held_symbol)
