                    self.held_symbol
                ))

    def ProcessExpirationSafety(self):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()

        if self.Time.date() >= expiry:
            self.no_entry_today = True
            if self.exit_ticket is None or self.exit_ticket.Status.IsClosed():
                self.CancelOpenExitOrders()
                self.exit_ticket = self.Liquidate(self.held_symbol)
                self.Debug("Expiration safety exit submitted: {}".format(
                    self.held_symbol
                ))

    def CancelOpenExitOrders(self):
        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            self.Transactions.CancelOrder(self.exit_ticket.OrderId)

    def OnOrderEvent(self, order_event):
        if order_event.Status != OrderStatus.Filled:
