        return universe.IncludeWeeklys().Strikes(-100, 100).Expiration(0, 365)

    def OnData(self, slice):
        self.current_slice = slice
        today = self.Time.date()

        if self.no_entries_today and today != getattr(self, "_blocked_date", None):
            self.no_entries_today = False

        if self.held_contract is not None:
            expiry = self.held_contract.ID.Date.date()

            if today >= expiry:
                self.no_entries_today = True
                self._blocked_date = today
                self.SubmitExit("expiration processing")
            else:
                self.CheckMinuteExit(expiry)

        spy_security = self.Securities[self.spy]
        if spy_security.Invested:
            self.Debug("Unexpected SPY equity position detected; liquidating immediately.")
            self.Liquidate(self.spy, "unexpected exercise or assignment")
            self.no_entries_today = True
            self._blocked_date = today

        self.consolidator.Update(slice.Bars[self.spy]) if self.spy in slice.Bars else None

    def OnFiveMinuteBar(self, sender, bar):
        bar_time = bar.EndTime.time()

        if bar_time < time(9, 30) or bar_time > time(16, 0):
            return

        if bar_time == time(9, 35):
            valid_interval = True
        elif self.last_completed_bar_end is None:
            valid_interval = False
        else:
            valid_interval = (
                bar.EndTime - self.last_completed_bar_end
                == timedelta(minutes=5)
            )

        self.last_completed_bar_end = bar.EndTime

        if not valid_interval:
            return

        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        eligible_time = time(9, 45) <= bar_time <= time(14, 30)
        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if eligible_time and bullish_cross:
            self.TryEnter()

    def TryEnter(self):
        if self.no_entries_today:
            return

        if self.held_contract is not None:
            return

        if self.entry_ticket is not None and self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ):
            return

        if self.current_slice is None or not self.current_slice.OptionChains:
            self.Debug("Skipped selection: no option chain in current Slice.")
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Skipped selection: invalid SPY price.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = []
        for chain in self.current_slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if (
                    contract.Right == OptionRight.Call
                    and contract.Expiry.date() >= minimum_expiry
                    and contract.Strike >= 1.01 * spy_price
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped selection: no qualifying call contract.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
        ]

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(f"Entry submitted: {selected.Symbol}")

    def CheckMinuteExit(self, expiry_date):
        if self.held_contract is None:
            return

        if (
            self.Time.time() >= time(15, 45)
            and self.IsTradingDayImmediatelyBefore(self.Time.date(), expiry_date)
        ):
            self.SubmitExit("pre-expiration time stop")
            return

        if self.entry_price is None:
            return

        contract_symbol = self.held_contract
        if contract_symbol not in self.current_slice.QuoteBars:
            return

        quote = self.current_slice.QuoteBars[contract_symbol]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("50% profit target")

    def SubmitExit(self, reason):
        if self.held_contract is None:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ):
            return

        quantity = -self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_contract,
            quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {reason}")

    def IsTradingDayImmediatelyBefore(self, current_date, expiry_date):
        if current_date >= expiry_date:
            return False

        date = current_date + timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(date):
            date += timedelta(days=1)

        return date == expiry_date

    def OnOrderEvent(self, order_event):
        if order_event.Status != OrderStatus.Filled:
            return

        symbol = order_event.Symbol

        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected exercise or assignment detected.")
            self.no_entries_today = True
            self._blocked_date = self.Time.date()
            self.Liquidate(self.spy, "unexpected exercise or assignment")
            return

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and symbol.SecurityType == SecurityType.Option
        ):
            self.held_contract = symbol
            self.entry_price = order_event.FillPrice
            self.Debug(
                f"Entry filled: {symbol}, price={self.entry_price:.4f}"
            )
            return

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            self.Debug(f"Exit filled: {symbol}, price={order_event.FillPrice:.4f}")
            self.held_contract = None
            self.entry_price = None
            self.exit_ticket = None
            self.entry_ticket = None

