        self.slow.Update(bar.EndTime, bar.Close)

        if not (self.fast.IsReady and self.slow.IsReady):
            return

        if previous_fast is None or previous_slow is None:
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        bar_end = bar.EndTime.astimezone(self.TimeZone).time()
        if not (
            bullish_cross
            and bar_end >= time(9, 45)
            and bar_end <= time(14, 30)
        ):
            return

        if self.expiration_day_blocked:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return

        self.TryEnterCall(bar.Close)

    def TryEnterCall(self, spy_price: float):
        if self.latest_slice is None or not self.latest_slice.OptionChains:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiration = self.Time.date() + timedelta(days=7)
        chains = list(self.latest_slice.OptionChains.Values)

        contracts = []
        for chain in chains:
            for contract in chain:
                expiration = contract.Expiry.date()
                if expiration >= minimum_expiration and contract.Right == OptionRight.Call:
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no qualifying expiration/contracts.")
            return

        nearest_expiration = min(c.Expiry.date() for c in contracts)
        strike_floor = 1.01 * spy_price
        candidates = [
            c for c in contracts
            if c.Expiry.date() == nearest_expiration
            and c.Right == OptionRight.Call
            and c.Strike >= strike_floor
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = sorted(
            candidates,
            key=lambda c: (c.Strike, str(c.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(f"Entry submitted: {selected.Symbol}")

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.held_option = order_event.Symbol
            self.entry_price = order_event.FillPrice
            self.Debug(
                f"Entry filled: {self.held_option}, price {self.entry_price}"
            )

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status.IsClosed()
        ):
            if self.held_option is not None and not self.Portfolio[self.held_option].Invested:
                self.Debug(f"Exit completed: {self.held_option}")
                self.held_option = None
                self.entry_price = None
                self.exit_ticket = None

    def ProcessOptionExit(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested:
            return

        quote = self.GetCurrentOptionQuote(slice, self.held_option)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self.SubmitOptionExit("profit target")

    def GetCurrentOptionQuote(self, slice: Slice, symbol: Symbol):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract.BidPrice, contract.AskPrice
        return None

    def ProcessExpiration(self):
        if self.held_option is None:
            return

        expiry = self.held_option.ID.Date.date()
        today = self.Time.date()

        if self.last_expiration_date != expiry and today >= expiry:
            self.last_expiration_date = expiry
            self.expiration_day_blocked = True
            self.SubmitOptionExit("expiration processing")

        elif today == expiry - timedelta(days=1):
            current_time = self.Time.time()
            if current_time >= time(15, 45):
                self.SubmitOptionExit("pre-expiration time stop")

    def SubmitOptionExit(self, reason: str):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            return

        quantity = -self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            self.entry_ticket.Cancel("Exit required before entry completion")

        self.exit_ticket = self.MarketOrder(self.held_option, quantity)
        self.Debug(f"Exit submitted ({reason}): {self.held_option}")

    def HandleUnexpectedEquityPosition(self):
        if self.Portfolio[self.spy].Quantity != 0:
            self.expiration_day_blocked = True
            self.Debug("Unexpected SPY equity position; liquidating immediately.")
            self.Liquidate(self.spy)

    def OnAssignmentOrderEvent(self, assignment_event: AssignmentOrderEvent):
        self.expiration_day_blocked = True
        self.Debug("Unexpected option exercise/assignment; liquidating SPY.")
        if self.Portfolio[self.spy].Quantity != 0:
            self.Liquidate(self.spy)

