            current_fast = sum(self.fast_values[i] for i in range(self.fast_period)) / self.fast_period
            current_slow = sum(self.slow_values[i] for i in range(self.slow_period)) / self.slow_period

            if (
                previous_fast is not None
                and previous_slow is not None
                and previous_fast <= previous_slow
                and current_fast > current_slow
            ):
                bar_end = bars[-1].EndTime
                local_end = Extensions.ConvertTo(bar_end, self.TimeZone)
                if Time(9, 45) <= local_end.time() <= Time(14, 30):
                    self._has_bullish_crossover = True

    def _enter_from_chain(self, slice: Slice):
        if self.option_symbol not in slice.OptionChains:
            self.Debug("Skipped entry: no option chain")
            return

        chain = slice.OptionChains[self.option_symbol]
        algorithm_date = self.Time.date()
        minimum_expiry = algorithm_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no valid expiration")
            return

        selected_expiry = expirations[0]
        underlying_price = float(self.Securities[self.spy_symbol].Price)
        minimum_strike = underlying_price * 1.01

