        self.entry_symbol = contract.Symbol
        self.entry_ticket = self.MarketOrder(contract.Symbol, 1)
        self.Debug(f"Entry submitted: {contract.Symbol}")

    def _evaluate_exit(self, slice: Slice):
        if self.entry_symbol is None or self.entry_symbol not in slice.Bars:
            quote = slice.QuoteBars.get(self.entry_symbol) if self.entry_symbol else None
        else:
            quote = slice.QuoteBars.get(self.entry_symbol)

        if quote is not None:
            bid = float(quote.Bid.Close)
            ask = float(quote.Ask.Close)
            if bid > 0 and ask > 0 and self.entry_price is not None:
                if (bid + ask) / 2 >= 1.5 * self.entry_price:
                    self._submit_exit("profit target")
                    return

        if (
            self.time_stop_date == self.Time.date()
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self._submit_exit("time stop")

    def _submit_exit(self, reason):
        if self.exit_ticket is not None and self.exit_ticket.Status in [
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        ]:
            return

        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            self.exit_ticket = self.Liquidate(self.entry_symbol)
            self.Debug(f"Exit submitted: {reason}")

    def _process_expiration_safety(self, slice: Slice):
        if self.expiration_date is not None and self.Time.date() >= self.expiration_date:
            if self._has_option_holding():
                self._submit_exit("expiration safety")
            self.block_entries_today = True

    def _has_option_holding(self):
        return (
            self.entry_symbol is not None
            and self.Portfolio[self.entry_symbol].Invested
        )

    def _entry_order_open(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.Status in [
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
            ]
        )

    def _eligible_signal_time(self):
        return Time(9, 45) <= self.Time.time() <= Time(14, 30)

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.entry_price = float(order_event.FillPrice)
            expiry = self.Securities[self.entry_symbol].Symbol.ID.Date
            self.expiration_date = expiry
            self.time_stop_date = self._prior_trading_day(expiry)
            self.Debug(f"Entry filled: {self.entry_symbol} @ {self.entry_price}")

        if order_event.Status == OrderStatus.Filled and getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected assignment: liquidating SPY")
            if self.Portfolio[self.spy_symbol].Invested:
                self.Liquidate(self.spy_symbol)
            self.block_entries_today = True

    def OnAssignmentOrderEvent(self, assignment_order_event):
        self.Debug("Unexpected exercise or assignment: liquidating SPY")
        if self.Portfolio[self.spy_symbol].Invested:
            self.Liquidate(self.spy_symbol)
        self.block_entries_today = True

    def _prior_trading_day(self, date):
        candidate = date - timedelta(days=1)
        hours = self.Securities[self.spy_symbol].Exchange.Hours
        while not hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)
        return candidate.date() if hasattr(candidate, "date") else candidate date

