class SpyCallCrossoverAlgorithm(QCAlgorithm):

    FAST_PERIOD = 5
    SLOW_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 365)
        )

        self.fast_values = RollingWindow[float](self.FAST_PERIOD)
        self.slow_values = RollingWindow[float](self.SLOW_PERIOD)

        self.bucket_end = None
        self.bucket_bars = []
        self.latest_slice = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.prevent_entry_today = False

    def OnData(self, slice: Slice):
        self.latest_slice = slice

        self._handle_unexpected_spy_position()
        self._handle_expiration_processing()

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsOpen():
            self.entry_ticket = None

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsOpen():
            self.exit_ticket = None

        self._evaluate_minute_exit()

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        self._process_minute_bar(bar)

    def _process_minute_bar(self, bar: TradeBar):
        end = bar.EndTime
        if end.tzinfo is not None:
            end = end.replace(tzinfo=None)

        if end.time() < time(9, 31) or end.time() > time(16, 0):
            return

        bucket_end = self._five_minute_bucket_end(end)

        if self.bucket_end is None:
            self.bucket_end = bucket_end

